import { useState } from "react";
import { X, Zap, CreditCard, CheckCircle, Tag, ShieldCheck, Copy, Check } from "lucide-react";
import api from "../../services/api";

const QR_IMAGE = "";

const PaymentModal = ({ course, onClose, onSuccess }) => {
  const [step, setStep] = useState("choose");
  const [paymentType, setPaymentType] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [copied, setCopied] = useState(false);

  if (!course) return null;

  const originalPrice = course.price || 0;
  const isFree = originalPrice === 0;
  const discountedPrice = Math.round(originalPrice * 0.9);
  const savings = originalPrice - discountedPrice;
  const installmentAmount = Math.round(originalPrice / 3);
  const installment2 = Math.round(originalPrice / 3);
  const installment3 = originalPrice - installmentAmount - installment2;
  const amountToPay = paymentType === "full" ? discountedPrice : installmentAmount;

  const handleProceed = () => {
    if (!paymentType && !isFree) return;
    setStep("confirm");
  };

  const handleShowQR = () => {
    setStep("qr");
  };

  const handlePaidConfirm = async () => {
    const token = localStorage.getItem("token");
    if (!token) { alert("Please login first!"); return; }
    setLoading(true);
    try {
      const res = await api.post(
        "/order/create",
        { courseId: course._id, paymentType: isFree ? "full" : paymentType },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      if (res.data.status) {
        setResult(res.data);
        setStep("success");
        onSuccess?.();
      } else {
        alert(res.data.message || "Payment failed");
      }
    } catch (err) {
      alert(err?.response?.data?.message || "Something went wrong");
    } finally {
      setLoading(false);
    }
  };

  const handleCopyUPI = () => {
    navigator.clipboard.writeText("lilabatipanigrahi@phonepe");
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <>
      <div onClick={onClose} style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.75)", backdropFilter:"blur(6px)", zIndex:100, animation:"pmFadeIn 0.2s ease" }} />

      <div style={{ position:"fixed", top:"50%", left:"50%", transform:"translate(-50%,-50%)", width:"min(520px, 95vw)", background:"#0f2027", border:"1px solid rgba(45,212,191,0.25)", borderRadius:20, boxShadow:"0 32px 80px rgba(0,0,0,0.7)", zIndex:101, overflow:"hidden", animation:"pmSlideUp 0.3s cubic-bezier(0.4,0,0.2,1)", fontFamily:"'DM Sans', sans-serif" }}>

        <style>{`
          @keyframes pmFadeIn { from { opacity:0 } to { opacity:1 } }
          @keyframes pmSlideUp { from { opacity:0; transform:translate(-50%,-42%) } to { opacity:1; transform:translate(-50%,-50%) } }
          @keyframes pmCheck { 0%{transform:scale(0.4);opacity:0} 60%{transform:scale(1.15)} 100%{transform:scale(1);opacity:1} }
          .pm-plan { border:2px solid rgba(45,212,191,0.15); border-radius:14px; padding:1.1rem 1.2rem; cursor:pointer; transition:all 0.2s; background:rgba(45,212,191,0.03); }
          .pm-plan:hover { border-color:rgba(45,212,191,0.4); background:rgba(45,212,191,0.06); }
          .pm-plan.selected { border-color:#2dd4bf; background:rgba(45,212,191,0.1); }
          .pm-plan.selected-full { border-color:#f97316; background:rgba(249,115,22,0.08); }
          .pm-pay-btn { width:100%; padding:14px; border-radius:12px; font-size:1rem; font-weight:800; border:none; cursor:pointer; font-family:"DM Sans",sans-serif; transition:all 0.2s; }
          .pm-pay-btn:hover:not(:disabled) { filter:brightness(1.1); transform:translateY(-1px); }
          .pm-pay-btn:disabled { opacity:0.6; cursor:wait; }
        `}</style>

        {/* Header */}
        <div style={{ padding:"1.4rem 1.6rem 1.2rem", borderBottom:"1px solid rgba(45,212,191,0.1)", background:"rgba(45,212,191,0.04)", display:"flex", alignItems:"flex-start", justifyContent:"space-between" }}>
          <div>
            <p style={{ fontSize:"0.65rem", fontWeight:700, color:"#2dd4bf", textTransform:"uppercase", letterSpacing:"0.12em", marginBottom:5 }}>
              {step === "success" ? "Payment Confirmed" : step === "qr" ? "Scan & Pay" : "Secure Checkout"}
            </p>
            <h2 style={{ fontSize:"1.05rem", fontWeight:800, color:"#e2faf8", margin:0, lineHeight:1.3, maxWidth:340 }}>{course.title}</h2>
          </div>
          <button onClick={onClose} style={{ background:"rgba(255,255,255,0.06)", border:"1px solid rgba(255,255,255,0.1)", borderRadius:8, padding:6, cursor:"pointer", color:"#a1a1aa", display:"flex", alignItems:"center", flexShrink:0, marginLeft:12 }}>
            <X size={16} />
          </button>
        </div>

        {/* ── STEP: Choose ── */}
        {step === "choose" && (
          <div style={{ padding:"1.5rem 1.6rem" }}>
            {isFree ? (
              <div style={{ textAlign:"center", padding:"1rem 0 1.5rem" }}>
                <div style={{ fontSize:"2.5rem", fontWeight:900, color:"#22c55e", marginBottom:8 }}>FREE</div>
                <p style={{ color:"rgba(226,250,248,0.5)", fontSize:"0.9rem" }}>This course is completely free. Click below to enroll.</p>
              </div>
            ) : (
              <>
                <p style={{ fontSize:"0.8rem", color:"rgba(226,250,248,0.45)", marginBottom:"1.2rem" }}>Choose your preferred payment plan:</p>

                {/* Full Payment */}
                <div className={`pm-plan${paymentType === "full" ? " selected-full" : ""}`} onClick={() => setPaymentType("full")} style={{ marginBottom:12 }}>
                  <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", gap:10 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                      <div style={{ width:38, height:38, borderRadius:10, flexShrink:0, background:paymentType==="full"?"rgba(249,115,22,0.2)":"rgba(249,115,22,0.1)", border:"1px solid rgba(249,115,22,0.3)", display:"flex", alignItems:"center", justifyContent:"center" }}>
                        <Zap size={17} color="#f97316" />
                      </div>
                      <div>
                        <p style={{ fontWeight:800, color:"#e2faf8", fontSize:"0.95rem", margin:0 }}>Full Payment</p>
                        <p style={{ fontSize:"0.72rem", color:"rgba(226,250,248,0.45)", margin:"2px 0 0" }}>Pay once, access forever</p>
                      </div>
                    </div>
                    <div style={{ textAlign:"right", flexShrink:0 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                        <span style={{ fontSize:"0.78rem", color:"#71717a", textDecoration:"line-through" }}>₹{originalPrice}</span>
                        <span style={{ fontSize:"1.1rem", fontWeight:900, color:"#f97316" }}>₹{discountedPrice}</span>
                      </div>
                      <span style={{ fontSize:"0.65rem", fontWeight:700, background:"rgba(249,115,22,0.15)", color:"#f97316", border:"1px solid rgba(249,115,22,0.3)", borderRadius:100, padding:"2px 8px" }}>10% OFF</span>
                    </div>
                  </div>
                  {paymentType === "full" && (
                    <div style={{ marginTop:12, padding:"10px 12px", borderRadius:9, background:"rgba(249,115,22,0.08)", border:"1px solid rgba(249,115,22,0.2)" }}>
                      <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4 }}>
                        <Tag size={11} color="#f97316" />
                        <span style={{ fontSize:"0.72rem", fontWeight:700, color:"#f97316" }}>You save ₹{savings}!</span>
                      </div>
                      <p style={{ fontSize:"0.7rem", color:"rgba(226,250,248,0.4)", margin:0 }}>One-time payment of ₹{discountedPrice} — best value</p>
                    </div>
                  )}
                </div>

                {/* Installment */}
                <div className={`pm-plan${paymentType === "installment" ? " selected" : ""}`} onClick={() => setPaymentType("installment")}>
                  <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", gap:10 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                      <div style={{ width:38, height:38, borderRadius:10, flexShrink:0, background:paymentType==="installment"?"rgba(45,212,191,0.2)":"rgba(45,212,191,0.1)", border:"1px solid rgba(45,212,191,0.3)", display:"flex", alignItems:"center", justifyContent:"center" }}>
                        <CreditCard size={17} color="#2dd4bf" />
                      </div>
                      <div>
                        <p style={{ fontWeight:800, color:"#e2faf8", fontSize:"0.95rem", margin:0 }}>3 Installments</p>
                        <p style={{ fontSize:"0.72rem", color:"rgba(226,250,248,0.45)", margin:"2px 0 0" }}>Split across 3 months</p>
                      </div>
                    </div>
                    <div style={{ textAlign:"right", flexShrink:0 }}>
                      <span style={{ fontSize:"1.1rem", fontWeight:900, color:"#2dd4bf" }}>₹{installmentAmount}</span>
                      <p style={{ fontSize:"0.68rem", color:"rgba(226,250,248,0.35)", margin:"2px 0 0" }}>/ month</p>
                    </div>
                  </div>
                  {paymentType === "installment" && (
                    <div style={{ marginTop:12 }}>
                      {[
                        { label:"1st Installment (Now)", amount:installmentAmount, color:"#22c55e", icon:"✓" },
                        { label:"2nd Installment (30 days)", amount:installment2, color:"#2dd4bf", icon:"○" },
                        { label:"3rd Installment (60 days)", amount:installment3, color:"#2dd4bf", icon:"○" },
                      ].map((inst, i) => (
                        <div key={i} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"8px 12px", background:i===0?"rgba(34,197,94,0.06)":"rgba(45,212,191,0.04)", borderRadius:8, marginBottom:i<2?4:0, border:`1px solid ${i===0?"rgba(34,197,94,0.15)":"rgba(45,212,191,0.1)"}` }}>
                          <div style={{ display:"flex", alignItems:"center", gap:7 }}>
                            <span style={{ fontSize:"0.7rem", color:inst.color, fontWeight:800 }}>{inst.icon}</span>
                            <span style={{ fontSize:"0.72rem", color:"rgba(226,250,248,0.55)" }}>{inst.label}</span>
                          </div>
                          <span style={{ fontSize:"0.82rem", fontWeight:800, color:inst.color }}>₹{inst.amount}</span>
                        </div>
                      ))}
                      <p style={{ fontSize:"0.68rem", color:"rgba(226,250,248,0.3)", margin:"8px 0 0" }}>Total: ₹{originalPrice} (no discount on installments)</p>
                    </div>
                  )}
                </div>
              </>
            )}

            <button className="pm-pay-btn" onClick={isFree ? handlePaidConfirm : handleProceed} disabled={!isFree && !paymentType}
              style={{ marginTop:"1.4rem", background:isFree?"#22c55e":paymentType==="full"?"#f97316":paymentType==="installment"?"#0d9488":"rgba(255,255,255,0.08)", color:!isFree&&!paymentType?"rgba(255,255,255,0.3)":"#fff" }}>
              {isFree ? "Enroll for Free" : !paymentType ? "Select a Payment Plan" : "Continue →"}
            </button>
          </div>
        )}

        {/* ── STEP: Confirm ── */}
        {step === "confirm" && (
          <div style={{ padding:"1.5rem 1.6rem" }}>
            <div style={{ background:"rgba(45,212,191,0.05)", border:"1px solid rgba(45,212,191,0.15)", borderRadius:14, padding:"1.2rem", marginBottom:"1.2rem" }}>
              <p style={{ fontSize:"0.68rem", fontWeight:700, color:"#2dd4bf", textTransform:"uppercase", letterSpacing:"0.1em", marginBottom:12 }}>Order Summary</p>
              <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:"0.85rem" }}>
                  <span style={{ color:"rgba(226,250,248,0.5)" }}>Course Price</span>
                  <span style={{ color:"#e2faf8", fontWeight:600 }}>₹{originalPrice}</span>
                </div>
                {paymentType === "full" && (
                  <>
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:"0.85rem" }}>
                      <span style={{ color:"#22c55e" }}>Discount (10%)</span>
                      <span style={{ color:"#22c55e", fontWeight:700 }}>− ₹{savings}</span>
                    </div>
                    <div style={{ height:1, background:"rgba(45,212,191,0.1)", margin:"4px 0" }} />
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:"1rem" }}>
                      <span style={{ color:"#e2faf8", fontWeight:700 }}>Total Payable</span>
                      <span style={{ color:"#f97316", fontWeight:900, fontSize:"1.1rem" }}>₹{discountedPrice}</span>
                    </div>
                  </>
                )}
                {paymentType === "installment" && (
                  <>
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:"0.85rem" }}>
                      <span style={{ color:"rgba(226,250,248,0.5)" }}>Payment Plan</span>
                      <span style={{ color:"#2dd4bf", fontWeight:600 }}>3 Installments</span>
                    </div>
                    <div style={{ height:1, background:"rgba(45,212,191,0.1)", margin:"4px 0" }} />
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:"1rem" }}>
                      <span style={{ color:"#e2faf8", fontWeight:700 }}>Pay Now (1st)</span>
                      <span style={{ color:"#2dd4bf", fontWeight:900, fontSize:"1.1rem" }}>₹{installmentAmount}</span>
                    </div>
                    <p style={{ fontSize:"0.72rem", color:"rgba(226,250,248,0.3)", margin:"2px 0 0" }}>Remaining ₹{originalPrice - installmentAmount} in 2 more installments</p>
                  </>
                )}
              </div>
            </div>

            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:"1.2rem", padding:"10px 12px", background:"rgba(34,197,94,0.06)", border:"1px solid rgba(34,197,94,0.15)", borderRadius:10 }}>
              <ShieldCheck size={15} color="#22c55e" />
              <span style={{ fontSize:"0.75rem", color:"rgba(226,250,248,0.5)" }}>100% Secure Payment · Instant Course Access</span>
            </div>

            <div style={{ display:"flex", gap:10 }}>
              <button onClick={() => setStep("choose")} style={{ flex:1, padding:"13px", borderRadius:12, background:"rgba(255,255,255,0.06)", border:"1px solid rgba(255,255,255,0.1)", color:"#a1a1aa", fontSize:"0.9rem", fontWeight:700, cursor:"pointer", fontFamily:"'DM Sans',sans-serif" }}>
                ← Back
              </button>
              <button className="pm-pay-btn" onClick={handleShowQR} style={{ flex:2, background:paymentType==="full"?"#f97316":"#0d9488", color:"#fff" }}>
                {paymentType === "full" ? `Pay ₹${discountedPrice} via PhonePe` : `Pay ₹${installmentAmount} via PhonePe`}
              </button>
            </div>
          </div>
        )}

        {/* ── STEP: QR ── */}
        {step === "qr" && (
          <div style={{ padding:"1.5rem 1.6rem" }}>
            {/* Amount badge */}
            <div style={{ textAlign:"center", marginBottom:"1rem" }}>
              <div style={{ display:"inline-block", background:"rgba(249,115,22,0.12)", border:"1px solid rgba(249,115,22,0.3)", borderRadius:12, padding:"8px 24px" }}>
                <span style={{ fontSize:"0.7rem", color:"rgba(226,250,248,0.5)", display:"block", marginBottom:2 }}>Amount to Pay</span>
                <span style={{ fontSize:"1.6rem", fontWeight:900, color:"#f97316" }}>₹{amountToPay}</span>
              </div>
            </div>

            {/* PhonePe header */}
            <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:10, marginBottom:"1rem" }}>
              <div style={{ width:32, height:32, borderRadius:"50%", background:"#5f259f", display:"flex", alignItems:"center", justifyContent:"center", fontSize:"18px" }}>₱</div>
              <div>
                <p style={{ fontWeight:800, color:"#e2faf8", fontSize:"0.95rem", margin:0 }}>PhonePe</p>
                <p style={{ fontSize:"0.7rem", color:"rgba(226,250,248,0.4)", margin:0 }}>Scan QR or pay via UPI</p>
              </div>
            </div>

            {/* QR Image */}
            <div style={{ display:"flex", justifyContent:"center", marginBottom:"1rem" }}>
              <div style={{ background:"#fff", borderRadius:16, padding:12, display:"inline-block", boxShadow:"0 8px 32px rgba(0,0,0,0.4)" }}>
                <img src={`data:image/jpeg;base64,${QR_IMAGE}`} alt="PhonePe QR Code" style={{ width:200, height:200, display:"block", borderRadius:8 }} />
              </div>
            </div>

            {/* Name */}
            <p style={{ textAlign:"center", fontSize:"0.85rem", fontWeight:700, color:"#e2faf8", marginBottom:"0.8rem", letterSpacing:"0.05em" }}>LILABATI PANIGRAHI</p>

            {/* UPI ID copy */}
            <div style={{ display:"flex", alignItems:"center", gap:8, background:"rgba(45,212,191,0.06)", border:"1px solid rgba(45,212,191,0.18)", borderRadius:10, padding:"10px 14px", marginBottom:"1.2rem" }}>
              <span style={{ flex:1, fontSize:"0.82rem", color:"#2dd4bf", fontWeight:600 }}>lilabatipanigrahi@phonepe</span>
              <button onClick={handleCopyUPI} style={{ background:"rgba(45,212,191,0.15)", border:"1px solid rgba(45,212,191,0.3)", borderRadius:7, padding:"4px 10px", cursor:"pointer", color:"#2dd4bf", display:"flex", alignItems:"center", gap:5, fontSize:"0.75rem", fontWeight:700 }}>
                {copied ? <><Check size={12}/> Copied!</> : <><Copy size={12}/> Copy</>}
              </button>
            </div>

            {/* Instruction */}
            <p style={{ textAlign:"center", fontSize:"0.78rem", color:"rgba(226,250,248,0.4)", marginBottom:"1.2rem", lineHeight:1.6 }}>
              Scan the QR with <strong style={{ color:"#fff" }}>PhonePe</strong> or any UPI app.<br/>
              After payment, click <strong style={{ color:"#22c55e" }}>I've Paid</strong> below.
            </p>

            <div style={{ display:"flex", gap:10 }}>
              <button onClick={() => setStep("confirm")} style={{ flex:1, padding:"13px", borderRadius:12, background:"rgba(255,255,255,0.06)", border:"1px solid rgba(255,255,255,0.1)", color:"#a1a1aa", fontSize:"0.9rem", fontWeight:700, cursor:"pointer", fontFamily:"'DM Sans',sans-serif" }}>
                ← Back
              </button>
              <button className="pm-pay-btn" onClick={handlePaidConfirm} disabled={loading}
                style={{ flex:2, background:"#22c55e", color:"#fff" }}>
                {loading ? "Verifying…" : "✓ I've Paid"}
              </button>
            </div>
          </div>
        )}

        {/* ── STEP: Success ── */}
        {step === "success" && (
          <div style={{ padding:"2rem 1.6rem", textAlign:"center" }}>
            <div style={{ width:72, height:72, borderRadius:"50%", background:"rgba(34,197,94,0.15)", border:"2px solid rgba(34,197,94,0.4)", display:"flex", alignItems:"center", justifyContent:"center", margin:"0 auto 1.2rem", animation:"pmCheck 0.5s cubic-bezier(0.4,0,0.2,1) both" }}>
              <CheckCircle size={36} color="#22c55e" />
            </div>
            <h3 style={{ fontFamily:"'Playfair Display', serif", fontSize:"1.4rem", fontWeight:900, color:"#e2faf8", marginBottom:8 }}>
              {paymentType === "full" ? "Payment Successful!" : "Enrolled Successfully!"}
            </h3>
            <p style={{ color:"rgba(226,250,248,0.5)", fontSize:"0.88rem", lineHeight:1.7, marginBottom:"1.4rem" }}>{result?.message}</p>
            {result?.order && (
              <div style={{ background:"rgba(45,212,191,0.05)", border:"1px solid rgba(45,212,191,0.15)", borderRadius:12, padding:"1rem", marginBottom:"1.4rem", textAlign:"left" }}>
                <div style={{ display:"flex", justifyContent:"space-between", marginBottom:6 }}>
                  <span style={{ fontSize:"0.75rem", color:"rgba(226,250,248,0.4)" }}>Transaction ID</span>
                  <span style={{ fontSize:"0.75rem", fontWeight:700, color:"#2dd4bf" }}>{result.order.transactionId}</span>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", marginBottom:6 }}>
                  <span style={{ fontSize:"0.75rem", color:"rgba(226,250,248,0.4)" }}>Amount Paid</span>
                  <span style={{ fontSize:"0.75rem", fontWeight:700, color:"#e2faf8" }}>₹{result.order.amountPaid}</span>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between" }}>
                  <span style={{ fontSize:"0.75rem", color:"rgba(226,250,248,0.4)" }}>Plan</span>
                  <span style={{ fontSize:"0.75rem", fontWeight:700, color:"#e2faf8", textTransform:"capitalize" }}>{result.order.paymentType}</span>
                </div>
              </div>
            )}
            <button onClick={onClose} style={{ width:"100%", padding:"13px", borderRadius:12, background:"#0d9488", color:"#fff", fontSize:"0.95rem", fontWeight:800, border:"none", cursor:"pointer", fontFamily:"'DM Sans', sans-serif" }}>
              Go to My Courses →
            </button>
          </div>
        )}
      </div>
    </>
  );
};

export default PaymentModal;